        void Pending(){if(StateSnapshot==null||closing||IsDisposed||Disposing)return;pending.Text=StateSnapshot.World.InitialSeed==(uint)seed.SelectedItem&&StateSnapshot.InitialPhase==phases[phase.SelectedIndex]&&StateSnapshot.PauseProfile==SelectedPause?"Controls match the applied copy.":"Selection pending. Load applies controls; Reset keeps the applied setup.";}
