        void Advance(int count)
        {
            if(closing||IsDisposed||Disposing)return;syncing=true;
            try{while(count-->0&&StateSnapshot.CanAdvance){PracticeReinforcementPhaseUpdate update;if(clockMode){var clockUpdate=clockSnapshot.AdvanceFrame();clockSnapshot=clockUpdate.State;StateSnapshot=clockSnapshot.Phase;update=clockUpdate.BodyUpdate;clockHistory.Add(StateSnapshot.Frames,clockUpdate);}else{update=StateSnapshot.AdvanceFrame();StateSnapshot=update.State;}history.Add(update);var ids=new List<string>();foreach(var fleet in update.State.World.LastCreated)ids.Add(fleet.Fleet.ToString());int row=trace.Rows.Add(StateSnapshot.Frames,update.GameClock,update.PauseWord,StateSnapshot.PhaseCounter,update.ConsumerPolled?"yes":"",update.State.World.LastCreated.Count);trace.Rows[row].Cells[5].ToolTipText="Fleet IDs: "+string.Join(" ",ids.ToArray());if(update.PauseWord!=0)trace.Rows[row].DefaultCellStyle.ForeColor=Color.Goldenrod;}if(history.Count>0){trace.CurrentCell=trace.Rows[history.Count-1].Cells[0];trace.FirstDisplayedScrollingRowIndex=history.Count-1;}}
            finally{syncing=false;}Sync();Inspect(history.Count==0?null:history[history.Count-1]);
