            if(update!=null){text.AppendFormat("Phase {0} -> {1}; supplied game clock {2}ms; pauseWORD {3}; driver {4}; consumer poll {5}.\r\n",update.Before.PhaseCounter,shown.PhaseCounter,update.GameClock,update.PauseWord,update.DriverCalled?"called":"skipped",update.ConsumerPolled?"yes":"no");text.Append("Caller scratch 0x"+update.CallerScratch.ToString("X8")+"; refresh-observed contact bytes: ");foreach(byte contact in update.RefreshContactBytes)text.Append(contact+" ");text.Append("; inactive F249contact now "+shown.ContactByte249+".\r\n");}
            if(clockMode){if(ShownClockUpdate!=null){var c=ShownClockUpdate;text.AppendFormat("CLOCK HEADER: sample {0}ms; body game {1}ms / OLD delta {2}ms; after game {3}ms / delta {4}ms; zero interval {5}.\r\n",c.SampleMilliseconds,c.BodyClock.GameMilliseconds,c.BodyClock.DeltaMilliseconds,c.State.Clock.GameMilliseconds,c.State.Clock.DeltaMilliseconds,c.ZeroInterval?"YES: epilogue resets to1":"no");}else text.Append("CLOCK HEADER prepared: previous11/current77/game0/delta13. Samples are supplied,not live pacing.\r\n");}text.Append("New fleets on the viewed frame (source group/slot order):\r\n");if(shown.World.LastCreated.Count==0)text.Append("  None.\r\n");foreach(var fleet in shown.World.LastCreated){text.AppendFormat("  Fleet {0}:group{1},slot{2},world{3},{4}; units",fleet.Fleet,fleet.Group,fleet.Slot,fleet.World.X,fleet.World.Y);foreach(int unit in fleet.Units)text.Append(" "+unit);text.Append("\r\n");}text.Append(clockMode?"\r\nOriginal1152frame clock corpus matches full cores,all before/body/after clocks and phase/contact metadata.\r\nWhole clock header;owned body/idle profile. No liveAI,movement,whole wait/render/input or pause-deadline compensation.":"\r\nOriginal1728frame corpus matched complete before/after cores,phase,pause,caller and refresh order.\r\nSupplied idle/zero-column profile only;this does not run liveAI, movement or the natural clock/pause-compensation loop.");details.Text=text.ToString();canvas.Invalidate();
