        void Draw(object sender,PaintEventArgs e)
        {
            var g=e.Graphics;g.Clear(BackColor);if(shown==null)return;g.SmoothingMode=SmoothingMode.AntiAlias;float size=Math.Min(canvas.ClientSize.Width-70,canvas.ClientSize.Height-65);if(size<=0)return;float left=45,top=28,scale=size/630;using(var pen=new Pen(Color.FromArgb(34,57,73)))using(var brush=new SolidBrush(Color.LightSteelBlue)){foreach(int value in new[]{0,200,400,630}){float at=value*scale;g.DrawLine(pen,left+at,top,left+at,top+size);g.DrawLine(pen,left,top+at,left+size,top+at);g.DrawString(value.ToString(),Font,brush,left+at-8,top-23);g.DrawString(value.ToString(),Font,brush,left-36,top+at-7);}}
            byte[] existing=shown.World.CopyExistingFleetPool(),pool=shown.World.CopyFleetPool();using(var pen=new Pen(Color.SlateGray,1.5f))for(int fleet=0;fleet<250;fleet++){int at=fleet*492;if(BitConverter.ToInt32(existing,at)==0)continue;float x=left+BitConverter.ToInt16(existing,at+12)*scale,y=top+BitConverter.ToInt16(existing,at+14)*scale;g.DrawRectangle(pen,x-3,y-3,6,6);}var ids=shown.World.FleetIds();Color[] colors={Color.CornflowerBlue,Color.Orange,Color.MediumSeaGreen,Color.Violet};foreach(int fleet in ids){int at=fleet*492,group=BitConverter.ToInt16(pool,at+6);float x=left+BitConverter.ToInt16(pool,at+12)*scale,y=top+BitConverter.ToInt16(pool,at+14)*scale;bool last=fleet==ids[ids.Count-1];using(var pen=new Pen(last?Color.Gold:colors[group],last?3:2))g.DrawEllipse(pen,x-5,y-5,10,10);if(last)using(var brush=new SolidBrush(Color.Gold))g.DrawString("Fleet "+fleet,Font,brush,Math.Min(left+size-60,x+8),Math.Max(top+4,y-17));}
